SELECT CAST(COUNT(DISTINCT CASE WHEN p.drug IN ('insulin', 'metformin', 'sulfonylurea', 'DPP-4', 'SGLT2', 'GLP-1', 'TZD') AND (p.charttime BETWEEN a.admittime AND a.dischtime) OR (p.charttime BETWEEN (a.dischtime - INTERVAL '72 hours') AND a.dischtime) THEN p.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) * 100 AS percentage FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id WHERE a.subject_id = 757071 AND p.gender = 'F' AND CAST(a.age AS INTEGER) BETWEEN 69 AND 79 AND d.icd_code IN ('654', '655', '656', '657', '658', '659', '660');